<?php
// نامه‌های اداری: پیش‌نویس ← نهایی (شمارهٔ ۵ رقمی از عددِ پایه) ← چاپ روی سربرگ با مهر و امضا
$id = req_int('id'); $l = $id ? row("SELECT * FROM letters WHERE id=?", [$id]) : null;
$f = ['d' => ['تاریخ', 'date', 1], 'subject' => ['موضوع', 'text', 1], 'to_name' => ['گیرنده', 'text'], 'to_title' => ['سمت/سازمانِ گیرنده', 'text'], 'body' => ['متن', 'textarea', 1], 'cc' => ['رونوشت', 'text'], 'attach_note' => ['پیوست', 'text'], 'stamp_on' => ['مهر', 'check'], 'sign_on' => ['امضا', 'check']];
if ($l) { echo ui_card('نامه ' . ($l['full_no'] ? fa_num($l['full_no']) : '(پیش‌نویس)'), '<div class="actions"><a class="btn" target="_blank" href="' . h(page_url('letters', ['print' => $l['id']])) . '">پیش‌نمایش و چاپ</a> ' . ($l['status'] === 'draft' ? ui_btn_api('نهایی و شماره‌گذاری', 'letter_final', ['id' => $l['id']], ['class' => 'primary', 'confirm' => 'پس از نهایی شدن ویرایش نمی‌شود. نهایی شود؟']) . ' ' . ui_btn_api('حذفِ پیش‌نویس', 'letter_delete', ['id' => $l['id']], ['class' => 'sm', 'confirm' => 'حذف شود؟', 'then' => 'go:' . page_url('letters')]) : '') . '</div>'
    . ($l['status'] === 'draft' ? ui_form('letter_save', $f, $l, ['hidden' => ['id' => $l['id']]]) : '<p class="muted">نهایی شده در ' . jdate((string)$l['finalized_at'], true) . '</p>')); }
else echo ui_card('نامهٔ تازه', ui_form('letter_save', $f, ['d' => today(), 'stamp_on' => 1, 'sign_on' => 1], ['then' => 'go:index.php?p=letters&id={id}', 'submit' => 'ذخیرهٔ پیش‌نویس']));
echo ui_card('نامه‌ها', ui_table(['full_no' => ['شماره', fn($r) => h(fa_num((string)($r['full_no'] ?: '—')))], 'd' => ['تاریخ', 'date'], 'subject' => 'موضوع', 'to_name' => 'گیرنده', 'status' => ['وضعیت', fn($r) => ui_badge($r['status'] === 'final' ? 'نهایی' : 'پیش‌نویس', $r['status'] === 'final' ? 'ok' : 'warn')]], rows("SELECT * FROM letters ORDER BY id DESC LIMIT 300"), ['filter' => 1, 'href' => fn($r) => page_url('letters', ['id' => $r['id']])]));
if (can('settings.edit')) echo ui_card('سربرگ', ui_form('settings_save', ['letter_no_start' => ['شمارهٔ آغاز', 'int'], 'letter_no_format' => ['قالبِ شماره ({no} {y} {yy} {m})', 'ltr'], 'letter_tagline' => ['زیرِ نام در سربرگ', 'text'], 'letter_signer' => ['نام و سمتِ امضاکننده', 'text']],
    ['letter_no_start' => setting('letter_no_start', '10250'), 'letter_no_format' => setting('letter_no_format', '{no}/{y}'), 'letter_tagline' => setting('letter_tagline', ''), 'letter_signer' => setting('letter_signer', '')]) . '<p class="muted">لوگو، مهر و امضا از «پروفایلِ کسب‌وکار».</p>');
